using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GhostlyLampOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/GhostlyLamp Omen Data")]
public class GhostlyLampOmenData : OnPlayerCorruptAfflictionOmenData
{
	[Header("Ghostly Lamp Omen Data")]
	[SerializeField]
	private SoulHeat soulHeat;

	private Action<int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(int corruptAfflictionAmount)
		{
			if (IsMinimunCorruptAmount(corruptAfflictionAmount))
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				soulHeat.ModifySoulHeat(1);
			}
		};
		ReferenceSingleton<SothisOmensHandler>.Instance.OnPlayerOrSentinelCorruptAfflictionSingleTimeOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.OnPlayerOrSentinelCorruptAfflictionSingleTimeOmenActions.Remove(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		return base.OmenConvertedDescription() + base.localizationManager.GetLocalizedIncreasesSoulHeatHeatID(1);
	}
}
